<section class="content-header"><h1><i class="fa fa-check-square-o"></i> Reporte de abordaje</h1></section><section class="content">
<div class="box box-primary no-print"><div class="box-body"><form method="get" class="form-inline"><label>Desde</label> <input type="date" name="desde" class="form-control" value="<?php echo html_escape($filtros['desde']);?>"> <label>Hasta</label> <input type="date" name="hasta" class="form-control" value="<?php echo html_escape($filtros['hasta']);?>"> <select name="viaje_id" class="form-control"><option value="0">Todos los viajes</option><?php foreach($viajes as $v):?><option value="<?php echo $v['viaje_id'];?>" <?php echo $filtros['viaje_id']==$v['viaje_id']?'selected':'';?>>#<?php echo $v['viaje_id'];?> - <?php echo html_escape($v['viaje_fecha'].' '.$v['viaje_horasalida'].' - '.$v['ruta']);?></option><?php endforeach;?></select> <label class="checkbox-inline"><input type="checkbox" name="solo_no_show" value="1" <?php echo $filtros['solo_no_show']==1?'checked':'';?>> Solo NO SHOW</label> <button class="btn btn-primary"><i class="fa fa-search"></i> Generar</button></form></div></div>
<div class="row"><div class="col-md-3"><div class="small-box bg-aqua"><div class="inner"><h3><?php echo (int)$resumen['vendidos'];?></h3><p>VENDIDOS</p></div><div class="icon"><i class="fa fa-ticket"></i></div></div></div><div class="col-md-3"><div class="small-box bg-green"><div class="inner"><h3><?php echo (int)$resumen['abordados'];?></h3><p>ABORDADOS</p></div><div class="icon"><i class="fa fa-check"></i></div></div></div><div class="col-md-3"><div class="small-box bg-red"><div class="inner"><h3><?php echo (int)$resumen['no_show'];?></h3><p>NO PRESENTADOS</p></div><div class="icon"><i class="fa fa-user-times"></i></div></div></div><div class="col-md-3"><div class="small-box bg-yellow"><div class="inner"><h3><?php echo number_format($resumen['tasa_no_show'],1,',','.');?>%</h3><p>TASA NO SHOW</p></div><div class="icon"><i class="fa fa-percent"></i></div></div></div></div>
<div class="alert alert-warning"><b>NO SHOW:</b> pasaje vendido que no tiene registro de abordaje. Para viajes aún no concluidos, este valor debe interpretarse como pendiente de abordar y no como ausencia definitiva.</div>
<div class="box"><div class="box-header"><h3 class="box-title">Control de pasajeros</h3><div class="pull-right no-print"><button onclick="window.print()" class="btn btn-default btn-sm"><i class="fa fa-print"></i> Imprimir</button> <a class="btn btn-success btn-sm" href="<?php echo site_url('reporte_abordaje/csv').'?'.http_build_query($filtros);?>"><i class="fa fa-file-excel-o"></i> Excel/CSV</a></div></div><div class="box-body"><div class="table-responsive"><table class="table table-bordered table-striped"><thead><tr><th>Viaje</th><th>Pasaje</th><th>Pasajero</th><th>Asiento</th><th>Estado</th><th>Abordaje</th><th>Terminal</th></tr></thead><tbody><?php foreach($detalle as $r):?><tr class="<?php echo $r['estado_abordaje']=='NO SHOW'?'danger':'';?>"><td><?php echo html_escape($r['viaje']);?></td><td><?php echo html_escape($r['pasaje_numero']);?></td><td><b><?php echo html_escape($r['pasajero']);?></b><br><small><?php echo html_escape($r['documento']);?></small></td><td><?php echo html_escape($r['asiento']);?></td><td><?php if($r['estado_abordaje']=='ABORDADO'):?><span class="label label-success">ABORDADO</span><?php else:?><span class="label label-danger">NO SHOW</span><?php endif;?></td><td><?php echo html_escape(trim($r['abordaje_fecha'].' '.$r['abordaje_hora']));?></td><td><?php echo html_escape($r['terminal']);?></td></tr><?php endforeach;?></tbody></table></div></div></div></section><style media="print">.no-print,.main-header,.main-sidebar,.content-header,.main-footer{display:none!important}.content-wrapper{margin-left:0!important}.content{padding:0!important}table{font-size:9px!important}</style>
